result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "test_hp_cop.py", "content": "import subprocess
import sys

import pytest

from hp_cop import carnot_fridge_cop, carnot_hp_cop, actual_cop


def run(*argv):
    return subprocess.run(
        [sys.executable, "hp_cop.py", *argv], capture_output=True, text=True
    )


def test_limit_heatpump():
    r = run("limit", "--mode", "heatpump", "--th", "308", "--tc", "273")
    assert r.returncode == 0
    assert r.stdout.strip() == "8.80"


def test_limit_fridge():
    r = run("limit", "--mode", "fridge", "--th", "308", "--tc", "258")
    assert r.returncode == 0
    assert r.stdout.strip() == "5.16"


def test_measured_plausible():
    r = run(
        "measured", "--heat-out", "5600", "--power-in", "1600",
        "--th", "308", "--tc", "273",
    )
    assert r.returncode == 0
    assert r.stdout.strip() == "3.50"
    assert r.stderr == ""


def test_measured_impossible():
    r = run(
        "measured", "--heat-out", "20000", "--power-in", "500",
        "--th", "308", "--tc", "273",
    )
    assert r.returncode == 3
    assert "thermodynamically impossible" in r.stderr


def test_invalid_temperatures_th_le_tc():
    r = run("limit", "--mode", "heatpump", "--th", "273", "--tc", "273")
    assert r.returncode == 2
    assert r.stderr.strip() != ""


def test_invalid_powers_negative():
    r = run(
        "measured", "--heat-out", "-1", "--power-in", "1600",
        "--th", "308", "--tc", "273",
    )
    assert r.returncode == 2
    assert r.stderr.strip() != ""


# ---- direct unit tests against formulas to 1e-12 ----

def test_carnot_hp_formula():
    for th, tc in [(308.0, 273.0), (330.0, 300.0), (400.0, 250.0)]:
        assert carnot_hp_cop(th, tc) == pytest.approx(th / (th - tc), rel=1e-12)


def test_carnot_fridge_formula():
    for th, tc in [(308.0, 258.0), (330.0, 300.0), (400.0, 250.0)]:
        assert carnot_fridge_cop(th, tc) == pytest.approx(tc / (th - tc), rel=1e-12)


def test_actual_cop_formula():
    for q, w in [(5600.0, 1600.0), (20000.0, 500.0), (1234.5, 678.9)]:
        assert actual_cop(q, w) == pytest.approx(q / w, rel=1e-12)
